{
  "schemaVersion": "scene-document/v2",
  "visualDecision": "scene",
  "source": {
    "question": "A continuous production model uses real quantities x and y. Its constraints are x >= 1/2, y >= 0, x + 2y <= 7, and 3x + y <= 8. Draw and shade the common feasible region, label every exact corner, and maximise profit F = 4x + 5y. Put F at each corner and mark every maximiser. Mark A = (1,1), B = (0,1), C = (9/5,13/5), and state feasibility. Fractional production is permitted.",
    "representationTier": "quantitative_verified",
    "nonMetric": false
  },
  "quantities": [
    {"id":"xmin","symbol":"x_min","value":0.5},
    {"id":"ymin","symbol":"y_min","value":0},
    {"id":"c1","symbol":"c_1","value":7},
    {"id":"c2","symbol":"c_2","value":8},
    {"id":"fx","symbol":"f_x","value":4},
    {"id":"fy","symbol":"f_y","value":5},
    {"id":"ax","symbol":"x_A","value":1},
    {"id":"ay","symbol":"y_A","value":1},
    {"id":"bx","symbol":"x_B","value":0},
    {"id":"by","symbol":"y_B","value":1},
    {"id":"cx","symbol":"x_C","value":1.8},
    {"id":"cy","symbol":"y_C","value":2.6}
  ],
  "entities": [
    {"id":"region","kind":"linear_region","role":"shaded common feasible region"},
    {"id":"v1","kind":"point","label":"(1/2,0)"},
    {"id":"v2","kind":"point","label":"(8/3,0)"},
    {"id":"c","kind":"point","label":"C"},
    {"id":"v4","kind":"point","label":"(1/2,13/4)"},
    {"id":"a","kind":"point","label":"A"},
    {"id":"b","kind":"point","label":"B"}
  ],
  "constructions": [
    {
      "id":"make_region",
      "operator":"linear_feasible_region",
      "inputs":{
        "variables":["x","y"],
        "constraints":["x >= 1/2","y >= 0","x + 2y <= 7","3x + y <= 8"],
        "objective":{"expression":"4x + 5y","sense":"max"}
      },
      "outputs":["region"]
    },
    {"id":"make_v1","operator":"point","inputs":{"x":0.5,"y":0,"coordinateSpace":"world"},"outputs":["v1"]},
    {"id":"make_v2","operator":"point","inputs":{"x":2.6666666666666665,"y":0,"coordinateSpace":"world"},"outputs":["v2"]},
    {"id":"make_c","operator":"point","inputs":{"x":"cx","y":"cy","coordinateSpace":"world"},"outputs":["c"]},
    {"id":"make_v4","operator":"point","inputs":{"x":0.5,"y":3.25,"coordinateSpace":"world"},"outputs":["v4"]},
    {"id":"make_a","operator":"point","inputs":{"x":"ax","y":"ay","coordinateSpace":"world"},"outputs":["a"]},
    {"id":"make_b","operator":"point","inputs":{"x":"bx","y":"by","coordinateSpace":"world"},"outputs":["b"]}
  ],
  "relations":[],
  "assertions":[],
  "annotations":[],
  "requiredEntityIds":["region","v1","v2","c","v4","a","b"],
  "revealGroups":[
    {"id":"setup","entityIds":["region","a","b","c"]},
    {"id":"corners","entityIds":["v1","v2","v4"]}
  ],
  "teachingTimeline":[
    {"id":"show_setup","revealGroupId":"setup"},
    {"id":"derive_corners","revealGroupId":"corners"},
    {
      "id":"evaluate",
      "targetIds":["v1","v2","c","v4"],
      "text":"In boundary order: F(1/2,0)=2; F(8/3,0)=32/3; F(9/5,13/5)=101/5; F(1/2,13/4)=73/4."
    },
    {
      "id":"conclude",
      "targetIds":["a","b","c"],
      "text":"A is feasible. B is infeasible because x<1/2. C is feasible and is the unique maximiser, with F=101/5."
    }
  ]
}

